presetParts.perFrame:
dec_med = exp (-7/fps);
dec_slow = exp (-1.5/fps);
beat = (bass+mid+treb)/3; 
avg = avg*dec_slow + beat*(1-dec_slow);
is_beat = above(beat, .2+avg+peak) * above (time, t0+.2);
t0 = is_beat*time + (1-is_beat)*t0;
peak = is_beat * beat + (1-is_beat)*peak*dec_med;
index = (index + is_beat) %16;
index2 = (index2 + is_beat*bnot(index))%4;

q22 = peak;
q24 = is_beat;
q26 = bass_att + mid_att + treb_att;
vol = vol*dec_med + (1-dec_med)*q26;
q27 = index + 1;
q28 = index2 +1;
q28 = 4+4*sin(time/13);


//****tunnel viewpoint x,y
vtrig = is_beat * bnot(index%4);
vx = vx * bnot(vtrig) + vtrig * (rand(100)/100-.5);
vy = vy * bnot(vtrig) + vtrig * (rand(100)/100-.5);
vx = vx* below(index%15,7); //###
vy = vy* below(index%15,7);
q5 = vx*20;
q6 = vy*20;

//***tunnel width
q21 = (1+sin(time/12))/16+.03;

//****tunnel rotation
rota = rota +.01*below(index%16,8)/fps*30;
rota1 = rota1*dec_med + (1-dec_med)*rota;
q7 = rota1/4;

//****tunnel speed
movez = movez + .01/(.1+abs(vx)+abs(vy))/fps;
q8 = movez * (q21*.01+1);
//dyn. Aenderung von q21 bewirkt auch Richt.wechsel

//***********************
trig1= q24*bnot(index%12);
trig2= q24*bnot((index+4)%12);
trig3= q24*bnot((index+8)%12);
trel = trel + vol/fps;
z0 = 2/q21;
hx = 4;
hy = 4;

p1z = z0;
q9 = 1*hx/(p1z); 
q10 = 0*hy/(p1z); 
q11 = p1z;
q12 = .1+.02*q26*bnot((index+2)%3)*p1z*exp(-p1z/100);

p2z = z0;
q13 = -.5*hx/(p2z); 
q14 = .87*hy/(p2z); 
q15 = p2z;
q16 = .1+.02*q26*bnot((index+2)%3)*p2z*exp(-p2z/100);

